function handleDiseaseCheckSearch(query) {
  const q = (query || '').trim().toLowerCase();
  const clearBtn = document.getElementById('diseaseCheckClearBtn');
  if (clearBtn) {
    clearBtn.style.display = q ? 'flex' : 'none';
  }

  const suggestArea = document.getElementById('diseaseCheckSuggestArea');
  const suggestPills = document.getElementById('diseaseCheckSuggestPills');

  if (!q) {
    if (suggestArea) suggestArea.style.display = 'none';
    if (suggestPills) suggestPills.innerHTML = '';
    const cards = document.querySelectorAll('#diseaseCheckContainer .disease-check-card');
    cards.forEach(card => card.style.display = 'block');
    return;
  }

  // 1. 超精密・処方鑑別データベースの検索
  const matchedDiffs = [];
  DRUG_DIFF_MAP.forEach(item => {
    const isMatched = item.drugs.some(d => d.toLowerCase().includes(q) || q.includes(d.toLowerCase()));
    if (isMatched) {
      item.diffs.forEach(diff => {
        if (!matchedDiffs.some(m => m.cardNum === diff.cardNum && m.subType === diff.subType)) {
          matchedDiffs.push(diff);
        }
      });
    }
  });

  // サジェストピル・病態特定カードの描画
  if (matchedDiffs.length > 0 && suggestArea && suggestPills) {
    suggestArea.style.display = 'block';
    suggestPills.innerHTML = matchedDiffs.map(d => `
      <div class="diff-subtype-card" onclick="jumpToDiseaseCard(${d.cardNum}, '${q}')" style="width:100%; box-sizing:border-box;">
        <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:6px; margin-bottom:2px;">
          <span class="diff-badge-subtype">${d.subType}</span>
          <strong style="font-size:0.88rem; color:#065f46;">📌 ${d.name} ➔ チェックへ</strong>
        </div>
        <div class="diff-criteria-text">${d.criteria}</div>
        <div style="font-size:0.77rem; color:#334155; line-height:1.45; margin-top:2px;">
          <strong>💡 臨床根拠：</strong>${d.reason}
        </div>
        <div class="diff-keypoint-text">
          <strong>⚠️ 確認急所：</strong>${d.keyPoint}
        </div>
      </div>
    `).join('');
  } else if (suggestArea) {
    suggestArea.style.display = 'none';
  }

  // 2. 全46疾患カードのリアルタイム絞り込み
  const cards = document.querySelectorAll('#diseaseCheckContainer .disease-check-card');
  cards.forEach(card => {
    const text = card.textContent.toLowerCase();
    const isDirectMatched = matchedDiffs.some(d => {
      const titleEl = card.querySelector('strong');
      return titleEl && titleEl.textContent.trim().startsWith(d.cardNum + '.');
    });
    if (text.includes(q) || isDirectMatched) {
      card.style.display = 'block';
    } else {
      card.style.display = 'none';
    }
  });
}

function clearDiseaseCheckSearch() {
  const input = document.getElementById('diseaseCheckSearchInput');
  if (input) input.value = '';
  handleDiseaseCheckSearch('');
}

function quickDiseaseSearch(keyword) {
  const input = document.getElementById('diseaseCheckSearchInput');
  if (input) {
    input.value = keyword;
    handleDiseaseCheckSearch(keyword);
    input.focus();
  }
}

function jumpToDiseaseCard(cardNum, drugKeyword) {
  const cards = document.querySelectorAll('#diseaseCheckContainer .disease-check-card');
  let targetCard = null;
  cards.forEach(card => {
    const titleEl = card.querySelector('strong');
    if (titleEl && titleEl.textContent.trim().startsWith(cardNum + '.')) {
      targetCard = card;
      card.style.display = 'block';
    }
  });

  if (targetCard) {
    targetCard.scrollIntoView({ behavior: 'smooth', block: 'center' });
    targetCard.classList.remove('diff-card-highlight');
    void targetCard.offsetWidth; // reflow
    targetCard.classList.add('diff-card-highlight');
    setTimeout(() => {
      targetCard.classList.remove('diff-card-highlight');
    }, 2500);
  }
}


// --- サジェストからの直接ジャンプ＆ハイライト関数 ---
function jumpToDrugDirectly(drug) {
  const dropdown = document.getElementById('suggest-dropdown');
  if (dropdown) dropdown.style.display = 'none';
  const sBox = document.getElementById('suggestBox');
  if (sBox) sBox.style.display = 'none';

  if (!drug) return;

  const targetTab = (drug.gId && drug.gId.startsWith('tab-')) ? drug.gId : 'tab-guide';
  switchTab(targetTab);

  if (targetTab === 'tab-guide') {
    const cardId = drug.gId || 'all';
    filterGuideCard(cardId, null);
    const sideLink = document.querySelector(`.guide-nav-link[onclick*="'${cardId}'"]`);
    if (sideLink) {
      document.querySelectorAll('.guide-nav-link').forEach(l => l.classList.remove('active'));
      sideLink.classList.add('active');
    }
    setTimeout(() => {
      let targetElem = null;
      if (drug.subId) targetElem = document.getElementById(drug.subId);
      if (!targetElem && cardId !== 'all') targetElem = document.getElementById(cardId);
      if (targetElem) {
        // カード内の該当薬剤テキストを探してピンポイントスクロール
        const drugNameSimple = drug.name.split('/')[0].split(' ')[0].replace(/[（(].*$/, '').trim();
        const walker = document.createTreeWalker(targetElem, NodeFilter.SHOW_ELEMENT);
        let node;
        let foundRow = null;
        while ((node = walker.nextNode())) {
          if (node.children.length === 0 && node.innerText && node.innerText.includes(drugNameSimple)) {
            foundRow = node.closest('tr') || node.closest('.pearl-box') || node.closest('.point-box') || node;
            break;
          }
        }
        smoothScrollToElement(foundRow || targetElem);
      }
    }, 120);
  } else if (targetTab === 'tab-newdrugs') {
    filterTrend(drug.cSec || 'all', null);
    setTimeout(() => {
      let sec = null;
      if (drug.cSec) sec = document.querySelector('#tab-newdrugs .' + drug.cSec);
      if (!sec) sec = document.querySelector('#tab-newdrugs');
      smoothScrollToElement(sec);
    }, 120);
  } else if (targetTab === 'tab-special') {
    showTopic(drug.cSec || 'all', null);
    setTimeout(() => {
      let sec = null;
      if (drug.cSec) sec = document.querySelector('#tab-special .' + drug.cSec);
      if (!sec) sec = document.querySelector('#tab-special');
      smoothScrollToElement(sec);
    }, 120);
  } else if (targetTab === 'tab-otc') {
    showOtc(drug.cSec || 'all', null);
    setTimeout(() => {
      let sec = null;
      if (drug.cSec) sec = document.querySelector('#tab-otc .' + drug.cSec);
      if (!sec) sec = document.querySelector('#tab-otc');
      smoothScrollToElement(sec);
    }, 120);
  } else if (targetTab === 'tab-followup') {
    showFu(drug.cSec || 'all', null);
    setTimeout(() => {
      let sec = null;
      if (drug.cSec) sec = document.querySelector('#tab-followup .' + drug.cSec);
      if (!sec) sec = document.querySelector('#tab-followup');
      smoothScrollToElement(sec);
    }, 120);
  } else if (targetTab === 'tab-comparison') {
    filterCompSec(drug.cSec || 'all', null);
    setTimeout(() => {
      let sec = null;
      if (drug.cSec) sec = document.querySelector('#tab-comparison .' + drug.cSec);
      if (!sec) sec = document.querySelector('#tab-comparison');
      smoothScrollToElement(sec);
    }, 120);
  }
}

// --- 12. 詳細モーダル＆ジャンプ関数 ---
function showDrugDetail(drug) {
  const modal = document.getElementById('drugDetailModal');
  const body = document.getElementById('modalDrugBody');
  if (!modal || !body) return;
  
  const isSpecialTab = drug.gId && drug.gId.startsWith('tab-');
  const guideBtnText = isSpecialTab ? '📑 該当セクションへジャンプ' : '📘 疾患ガイドへジャンプ';
  const guideAction = isSpecialTab 
    ? `jumpToSpecialTab('${drug.gId}', '${drug.cSec}')` 
    : (drug.subId ? `jumpToGuide('${drug.gId}', '${drug.subId}')` : `jumpToGuide('${drug.gId}')`);
  
  const searchKeyword = drug.name.split('/')[0].split(' ')[0].split('（')[0].replace(/[0-9]/g, '').trim();
  const compBtn = (!isSpecialTab && drug.cSec) 
    ? `<button onclick="jumpToComp('${drug.cSec}', '${searchKeyword}')" style="background:#0f766e; color:white; border:none; padding:8px 16px; border-radius:6px; font-weight:700; cursor:pointer; font-size:0.85rem;">⚔️ 同効薬比較へジャンプ</button>`
    : '';

  
  const compInfo = getCompoundingInfo(drug.name, drug.gen);
  const compBoxHtml = compInfo ? `
    <div style="background:#f8fafc; border:1px solid #cbd5e1; border-radius:8px; padding:12px 14px; margin-bottom:14px;">
      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:8px;">
        <strong style="color:#1e293b; font-size:0.92rem; display:flex; align-items:center; gap:6px;">
          <span>🧪</span> 粉砕・一包化・簡易懸濁 適合性チェック
        </strong>
        <button onclick="jumpToCrush('${compInfo.key || drug.name}')" style="background:#4f46e5; color:white; border:none; padding:4px 10px; border-radius:4px; font-size:0.75rem; font-weight:700; cursor:pointer;">全80大表で確認 ➔</button>
      </div>
      <div style="display:grid; grid-template-columns:repeat(auto-fit, minmax(130px, 1fr)); gap:8px; margin-bottom:8px;">
        <div style="background:white; border:1px solid #e2e8f0; border-radius:6px; padding:6px 10px;">
          <span style="font-size:0.74rem; color:#64748b;">💊 粉砕可否</span>
          <div style="font-size:0.92rem; font-weight:800; margin-top:2px;">${compInfo.crushText}</div>
        </div>
        <div style="background:white; border:1px solid #e2e8f0; border-radius:6px; padding:6px 10px;">
          <span style="font-size:0.74rem; color:#64748b;">💧 簡易懸濁 (55℃)</span>
          <div style="font-size:0.92rem; font-weight:800; margin-top:2px;">${compInfo.suspText}</div>
        </div>
        <div style="background:white; border:1px solid #e2e8f0; border-radius:6px; padding:6px 10px;">
          <span style="font-size:0.74rem; color:#64748b;">📦 一包化適否</span>
          <div style="font-size:0.92rem; font-weight:800; margin-top:2px;">${compInfo.packText}</div>
        </div>
      </div>
      <div style="font-size:0.8rem; color:#475569; line-height:1.45;">
        <strong>理由・代替案：</strong> ${compInfo.reason} (推奨代替: ${compInfo.alt})
      </div>
    </div>
  ` : '';
const isDrugFav = (typeof isFavorite === 'function') && isFavorite('dict_' + drug.name);
  const favBtnHtml = `
    <button class="fav-btn ${isDrugFav ? 'active' : ''}" 
            data-fav-id="dict_${drug.name}" 
            onclick="toggleFavorite({ id: 'dict_${drug.name}', title: '${drug.name}', category: '💊 臨床事典 / 薬剤', type: 'drug', desc: '${(drug.char || drug.desc || '').replace(/'/g, "\\'")}', tabId: 'tab-dict', action: 'showDrugByName(\\\'${drug.name}\\\' )' }, this)" 
            title="${isDrugFav ? 'お気に入りを解除' : 'お気に入りに追加'}" 
            style="font-size:1.35rem; padding:2px 8px;">
      ${isDrugFav ? '★' : '☆'}
    </button>
  `;
body.innerHTML = `
    <div style="border-bottom:2px solid #e2e8f0; padding-bottom:12px; margin-bottom:14px;">
      <span style="display:inline-block; background:#e0f2fe; color:#0369a1; font-weight:700; font-size:0.78rem; padding:3px 10px; border-radius:4px; margin-bottom:6px;">${drug.cat}</span>
      <div style="display:flex; justify-content:space-between; align-items:center;">
        <h2 style="font-size:1.35rem; color:var(--primary); font-weight:800; margin:0;">${drug.name}</h2>
        ${favBtnHtml}
      </div>
      <div style="font-size:0.88rem; color:#64748b; margin-top:2px;">一般名：${drug.gen}</div>
    </div>
    <div style="background:#eff6ff; border-left:4px solid #2563eb; padding:10px 14px; border-radius:6px; margin-bottom:14px;">
      <strong style="color:#1e3a8a; font-size:0.92rem;">🎯 キャラ・一言：</strong>
      <div style="font-size:0.88rem; color:#1e293b; margin-top:2px;">${drug.char}</div>
    </div>
    ${compBoxHtml}
    <div style="font-size:0.9rem; line-height:1.65; color:#334155; margin-bottom:20px;">
      <strong>💡 現場の勘所・ピットフォール：</strong><br>
      ${drug.desc}
    </div>
    <div style="display:flex; gap:10px; flex-wrap:wrap; justify-content:flex-end;">
      <button onclick="closeDrugModal(); jumpToDiseaseCheck('all'); quickDiseaseSearch('${drug.name}');" style="background:#059669; color:white; border:none; padding:8px 16px; border-radius:6px; font-weight:700; cursor:pointer; font-size:0.85rem; box-shadow:0 1px 3px rgba(5,150,105,0.3);">🩺 処方鑑別 ＆ 症状・薬剤確認へ</button>
      <button onclick="${guideAction}" style="background:#2563eb; color:white; border:none; padding:8px 16px; border-radius:6px; font-weight:700; cursor:pointer; font-size:0.85rem;">${guideBtnText}</button>
      ${compBtn}
      <button onclick="closeDrugModal()" style="background:#f1f5f9; color:#475569; border:1px solid #cbd5e1; padding:8px 16px; border-radius:6px; font-weight:700; cursor:pointer; font-size:0.85rem;">閉じる</button>
    </div>
  `;
  modal.style.display = 'flex';
}

function closeDrugModal() {
  const modal = document.getElementById('drugDetailModal');
  if (modal) modal.style.display = 'none';
}

function jumpToGuide(cardId, subId) {
  closeDrugModal();
  switchTab('tab-guide');
  filterGuideCard(cardId, null);
  const targetId = subId || cardId;
  const target = document.getElementById(targetId);
  if (target) {
    smoothScrollToElement(target);
  }
}

function jumpToComp(secClass, keyword) {
  closeDrugModal();
  switchTab('tab-comparison');
  filterCompSec(secClass, null);
  const sec = document.querySelector('.' + secClass);
  if (sec) {
    if (keyword) {
      const rows = sec.querySelectorAll('tbody tr');
      let targetRow = null;
      for (const row of rows) {
        if (row.innerText.includes(keyword)) {
          targetRow = row;
          break;
        }
      }
      if (targetRow) {
        smoothScrollToElement(targetRow);
        return;
      }
    }
    smoothScrollToElement(sec);
  }
}

function jumpToSpecialTab(tabId, secClass) {
  closeDrugModal();
  switchTab(tabId);
  if (tabId === 'tab-newdrugs') {
    filterTrend(secClass || 'all', null);
  } else if (tabId === 'tab-special') {
    showTopic(secClass || 'all', null);
  } else if (tabId === 'tab-otc') {
    showOtc(secClass || 'all', null);
  } else if (tabId === 'tab-followup') {
    showFu(secClass || 'all', null);
  }
  if (secClass && secClass !== 'all') {
    setTimeout(() => {
      const target = document.querySelector('.' + secClass);
      if (target) target.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }, 150);
  }
}

function initAllDrugsList() {
  const container = document.getElementById('allDrugsGridContainer');
  if (!container) return;
  container.innerHTML = '';
  
  DRUG_DB.forEach(drug => {
    const card = document.createElement('div');
    card.className = 'mini-drug-card';
    card.innerHTML = `
      <div style="font-weight:700; color:#1e3a8a; font-size:0.88rem; margin-bottom:2px;">${drug.name}</div>
      <div style="font-size:0.75rem; color:#64748b;">${drug.cat}</div>
    `;
    card.onclick = () => showDrugDetail(drug);
    container.appendChild(card);
  });
}

