// --- 15. 臨床インデックス辞書 スクリプト ---
let currentDictType = 'all';
let currentDictKana = 'all';
let currentDictQuery = '';

function applyDictFilters() {
  const cards = document.querySelectorAll('#dictCardsContainer .dict-card');
  cards.forEach(card => {
    const cType = card.getAttribute('data-type') || '';
    const cKana = card.getAttribute('data-kana') || '';
    const cName = card.getAttribute('data-name') || '';
    const cDesc = card.getAttribute('data-desc') || '';

    // タイプ判定
    const matchType = (currentDictType === 'all' || cType === currentDictType);
    
    // かな判定
    const matchKana = (currentDictKana === 'all' || cKana === currentDictKana);

    // テキスト検索判定
    const matchQuery = (!currentDictQuery || cName.includes(currentDictQuery) || cDesc.includes(currentDictQuery));

    if (matchType && matchKana && matchQuery) {
      card.style.display = 'flex';
    } else {
      card.style.display = 'none';
    }
  });
}

function filterDict(type, btn) {
  currentDictType = type;
  const btns = document.querySelectorAll('#tab-dict .dict-btn');
  btns.forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  applyDictFilters();
}

function filterDictSearch(query) {
  currentDictQuery = query.trim().toLowerCase();
  applyDictFilters();
}

function filterDictKana(kana) {
  currentDictKana = kana;
  applyDictFilters();
}

function showDrugByName(drugName) {
  const drug = DRUG_DB.find(d => d.name.includes(drugName) || drugName.includes(d.name.split(' ')[0]));
  if (drug) {
    jumpToDrugDirectly(drug);
  } else {
    // 汎用検索へフォールバック
    quickSearch(drugName);
  }
}

function jumpToAnswer(qId) {
  switchTab('tab-answers');
  const target = document.getElementById(qId);
  if (target) {
    smoothScrollToElement(target);
  }
}

function jumpToProfiling(proId) {
  switchTab('tab-profiling');
  const target = document.getElementById(proId);
  if (target) {
    smoothScrollToElement(target);
  }
}

// --- 14. 初期化処理 ---
document.addEventListener('DOMContentLoaded', () => {
  initDictCompoundingBadges();
  renderWeeklyTopics();
  initFavoritesButtons();
  updateFavoriteCountBadges();
  initAllDrugsList();
  
  // ヒーロー検索ボックスのイベント設定
  const heroInput = document.getElementById('drug-search-input');
  if (heroInput) {
    heroInput.addEventListener('input', () => handleHeroSearchInput(heroInput));
    heroInput.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        const d = document.getElementById('suggest-dropdown');
        if (d) d.style.display = 'none';
      } else if (e.key === 'Enter') {
        quickSearch(heroInput.value.trim());
      }
    });
  }

  // 小児計算機の初期描画
  calcPediatricDose(10);

  // 腎機能シミュレーターの初期描画
  calcRenalDose();

  // 外側クリックでサジェストボックスを閉じる
  document.addEventListener('click', (e) => {
    const sBox = document.getElementById('suggestBox');
    const sInput = document.getElementById('mainSearchInput');
    if (sBox && !sBox.contains(e.target) && e.target !== sInput) {
      sBox.style.display = 'none';
    }

    const dropdown = document.getElementById('suggest-dropdown');
    if (dropdown && !dropdown.contains(e.target) && e.target !== heroInput) {
      dropdown.style.display = 'none';
    }
  });
});


// --- 抗菌薬マスターナビゲーター切り替えスクリプト ---
function switchAbxView(viewId, btn) {
  const btns = document.querySelectorAll('.abx-tab-btn');
  btns.forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');

  const panes = document.querySelectorAll('.abx-view-pane');
  panes.forEach(p => p.classList.remove('active'));

  const target = document.getElementById(viewId);
  if (target) {
    target.classList.add('active');
  }
}


// --- 16. 臨床検査値評価タブ スクリプト ---
function filterLabSection(secClass, btn) {
  const btns = document.querySelectorAll('#tab-lab .dict-btn');
  btns.forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');

  const secs = document.querySelectorAll('#tab-lab .lab-section');
  secs.forEach(s => {
    if (secClass === 'all' || s.classList.contains(secClass)) {
      s.style.display = 'block';
    } else {
      s.style.display = 'none';
    }
  });
}

function filterLabTables() {
  const input = document.getElementById('labSearchInput');
  if (!input) return;
  const q = input.value.trim().toLowerCase();
  const rows = document.querySelectorAll('#tab-lab table tbody tr');
  rows.forEach(r => {
    const text = r.innerText.toLowerCase();
    if (!q || text.includes(q)) {
      r.style.display = '';
    } else {
      r.style.display = 'none';
    }
  });
}


// --- 🏆 薬局頻出TOP100 20位ごとレンジ切り替え ---
function filterTop100Range(rangeId, btn) {
  const panes = document.querySelectorAll('.top100-range-pane');
  panes.forEach(p => p.style.display = 'none');
  const target = document.getElementById('top100-range-' + rangeId);
  if (target) {
    target.style.display = 'block';
  }
  if (btn && btn.parentElement) {
    const btns = btn.parentElement.querySelectorAll('.filter-btn');
    btns.forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
  }
}


